import subprocess,re,json
u='prediction-a2z-v4-model@A2Z-V4-ASTRA-PREBUILD-DIRECT-20261007-R4P2.service'
p=subprocess.run(['journalctl','--user','-u',u,'--since','2026-10-07 21:13:15','--until','2026-10-07 21:13:26','--no-pager'],capture_output=True,text=True)
rows=[]
for line in (p.stdout or '').splitlines():
    r={}
    m=re.match(r'^([A-Z][a-z]{2} \\d{2} \\d{2}:\\d{2}:\\d{2}) ',line)
    if m:r['time']=m.group(1)
    if 'SUPERVISOR_STATE' in line:
        for k,pat in [('state',r'\"state\"\\s*:\\s*\"([^\"]+)\"'),('reason',r'\"reason\"\\s*:\\s*\"([^\"]+)\"'),('attempt',r'\"attempt\"\\s*:\\s*(\\d+)'),('checkpoint',r'\"checkpoint\"\\s*:\\s*\"([^\"]+)\"')]:
            z=re.search(pat,line)
            if z:r[k]=int(z.group(1)) if k=='attempt' else z.group(1)
        r['event']='SUPERVISOR_STATE'
    elif 'Main process exited' in line:
        r['event']='MAIN_EXIT'
        z=re.search(r'status=([^ ]+)',line)
        if z:r['status']=z.group(1)
    elif 'Failed with result' in line:r['event']='FAILED_RESULT'
    elif 'Started prediction-a2z-v4-model@' in line:r['event']='STARTED'
    elif 'Deactivated successfully' in line:r['event']='DEACTIVATED'
    else:continue
    rows.append(r)
print('ERROR_CLASS=R4P2_TEMPFAIL_TRANSITION',flush=True)
print('ERROR='+json.dumps(rows,separators=(',',':'),sort_keys=True),flush=True)
raise SystemExit(1)
